import{AuthService}from"./auth.service.js";export class StatisticsService{static async getStats(){const t=AuthService.getToken();if(!t)throw new Error("User is not authenticated");const a=await fetch("/api/stats",{headers:{Authorization:`Bearer ${t}`}}),e=await a.json();if(!a.ok)throw new Error(e.message||"Failed to fetch stats");return e.stats}static async updateStats(t){const a=AuthService.getToken();if(!a)throw new Error("User is not authenticated");const e=await fetch("/api/stats",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${a}`},body:JSON.stringify(t)}),r=await e.json();if(!e.ok)throw new Error(r.message||"Failed to update stats");return r.stats}static getRankFromWpm(t){return t>=100?{name:"Hacker",class:"rank-hacker"}:t>=70?{name:"Pro",class:"rank-pro"}:t>=50?{name:"Intermédiaire",class:"rank-intermediate"}:t>=30?{name:"Initié",class:"rank-initiate"}:{name:"Débutant",class:"rank-noob"}}}